import{_ as t,o,c as d,a6 as i}from"./chunks/framework.DtfPIzdJ.js";const q=JSON.parse('{"title":"Voice coding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/voice.md","filePath":"guide/voice.md"}'),c={name:"guide/voice.md"};function a(r,e,n,s,u,l){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="voice-coding" tabindex="-1">Voice coding <a class="header-anchor" href="#voice-coding" aria-label="Permalink to &quot;Voice coding&quot;">​</a></h1><p>Cluub is designed to be <strong>spoken</strong>. Keywords are ordinary English words, and every operator has a word form. That makes dictation tools such as <strong>Wispr Flow</strong> (or the dictation built into macOS, Windows and phones) practical for writing code.</p><table tabindex="0"><thead><tr><th>Say</th><th>Cluub</th></tr></thead><tbody><tr><td>&quot;if total is greater than one hundred&quot;</td><td><code>if total is greater than 100</code></td></tr><tr><td>&quot;require title is not empty comma quote title is required quote&quot;</td><td><code>require title is not empty, &quot;Title is required&quot;</code></td></tr><tr><td>&quot;let price equals cost times two&quot;</td><td><code>let price = cost times 2</code></td></tr><tr><td>&quot;return a divided by b&quot;</td><td><code>return a divided by b</code></td></tr><tr><td>&quot;if done and not archived&quot;</td><td><code>if done and not archived</code></td></tr><tr><td>&quot;button quote save quote comma on click save&quot;</td><td><code>button &quot;Save&quot;, on click save</code></td></tr><tr><td>&quot;ask ai quote summarize notes quote&quot;</td><td><code>ask ai &quot;summarize {notes}&quot;</code></td></tr></tbody></table><p>Accepted word forms: <code>is</code>, <code>is not</code>, <code>equals</code>, <code>is greater than</code>, <code>is less than</code>, <code>is at least</code>, <code>is at most</code>, <code>is empty</code>, <code>is one of</code>, <code>has</code>, <code>and</code>, <code>or</code>, <code>not</code>, <code>plus</code>, <code>minus</code>, <code>times</code>, <code>divided by</code>, <code>yes</code>/<code>no</code> for true/false.</p><h2 id="tips-for-dictation" tabindex="-1">Tips for dictation <a class="header-anchor" href="#tips-for-dictation" aria-label="Permalink to &quot;Tips for dictation&quot;">​</a></h2><ul><li>Dictate one line at a time; Cluub&#39;s indentation is 2 spaces per level, and the playground editor indents for you after lines like <code>if …</code>, <code>view</code>, <code>action …</code>.</li><li>If a word lands in the wrong place, <code>cluub dev</code> points at it immediately with a suggestion (&quot;Did you mean <code>heading</code>?&quot;).</li><li>Use <code>cluub make &quot;…&quot;</code> for bigger changes: say what you want in plain English and let the AI write the code.</li></ul>',6)])])}const p=t(c,[["render",a]]);export{q as __pageData,p as default};
